record WorkSummary(int EmployeeId, decimal Hours);

sealed class Report(string title)
{
    public required DateOnly Date { get; init; }
    public string Title { get; } = title;
}

WorkSummary first = new(1, 8m);
WorkSummary revised = first with { Hours = 7.5m };
WorkSummary[] summaries = [first, revised];
Report report = new("Daily hours") { Date = DateOnly.FromDateTime(DateTime.Today) };

Console.WriteLine($"{report.Title}: {summaries.Length}");
